static <T extends Serializable> void serializeToFile(T obj, Path path) throws IOException {
    try (ObjectOutputStream out = new ObjectOutputStream(new FileOutputStream(path.toFile()))) {
        out.writeObject(obj);
    }
}

@SuppressWarnings("unchecked")
static <T> T deserializeFromFile(Path path) throws IOException, ClassNotFoundException {
    try (ObjectInputStream in = new ObjectInputStream(new FileInputStream(path.toFile()))) {
        return (T) in.readObject();
    }
}

static class SafeDeserializer {
    Optional<Object> tryDeserialize(byte[] bytes) {
        try {
            return Optional.of(deserialize(bytes));
        } catch (InvalidClassException | ClassNotFoundException e) {
            return Optional.empty();
        } catch (IOException e) {
            return Optional.empty();
        }
    }
}

